"""Season 1 Audition Pack + Episodes E001–E003 for《基督山伯爵·伊夫堡复仇广播剧》.

Flagship 15–20 minute cinematic radio drama full editions (~3,150–3,500 CJK chars, ~68–88 cues,
16–22 SFX/motif cues each), freshly adapted from Alexandre Dumas's 100% globally public-domain 1844 classic
*Le Comte de Monte-Cristo*:
- AUDITION_MONTE_CRISTO: 核心声线与复仇名场面试听包 (~1.7 min)
- E001: 《订婚夜的黑信_马赛港法老号与伊夫堡铁门》
- E002: 《十四年石墙暗道_法利亚神父与装尸袋跃海》
- E003: 《荒岛黄金与幽灵归来_水手辛巴达与巴黎暗棋》
"""

from __future__ import annotations

from aigc_audio_pipeline.models import EpisodeCueSheet
from drama_helpers import act, dlg, motif, sfx


def build_audition_monte_cristo() -> EpisodeCueSheet:
    cues = [
        motif("ma01_bell", "audition", "marseille_harbor_bell", gap_after_s=0.22, director_note="马赛港法老号归航开篇"),
        dlg("ma02_narr", "audition", "narrator", "史诗旁白", "[solemn] 一八一五年二月二十四日，法老号满帆驶入马赛港。谁也没想到，一封藏在酒杯背后的黑信，会把十九岁的大副拖进十四年暗无天日的海中孤牢。", gap_after_s=0.24),
        motif("ma03_iron", "audition", "chateau_dif_iron_door", placement="overlay_next", gap_after_s=0.18),
        dlg("ma04_dantes", "audition", "dantes_young", "青年爱德蒙·唐泰斯", "[desperately] [shouting] 维尔福先生！今天是我和梅尔塞苔丝的订婚日！我连那封信里写了什么都不知道——你们凭什么把我活埋在伊夫堡！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.22),
        dlg("ma05_villefort", "audition", "villefort", "热拉尔·德·维尔福", "[coldly] [dismissive] 唐泰斯，你确实无罪。可你手里的信偏偏写着我父亲的名字。为了我的前程，这封信必须化作灰烬，而你必须永远消失。", acoustic_space="vintage_study", gap_after_s=0.24),
        motif("ma06_tap", "audition", "faria_wall_tap", gap_after_s=0.20),
        dlg("ma07_faria", "audition", "abbe_faria", "法利亚神父", "[whispers] [warmly] 别哭，孩子。仇恨若不装进智慧的剑鞘，只会先割伤你自己。贴近石墙，我把学识、真相与基督山岛的千年宝藏全都交给你。", acoustic_space="vast_hall", gap_after_s=0.26),
        motif("ma08_paris", "audition", "paris_salon_clock_glass", gap_after_s=0.22),
        dlg("ma09_count", "audition", "monte_cristo", "基督山伯爵", "[calmly] [coldly] 各位巴黎的贵客，不必惊慌。我不过是替上帝来结一笔迟到了二十三年的旧账——恩情加倍偿还，罪孽分毫不差。", acoustic_space="studio_warm", gap_after_s=0.24),
        dlg("ma10_mercedes", "audition", "mercedes", "梅尔塞苔丝", "[crying] [trembling] 伯爵……不，爱德蒙！这世上纵然所有人都忘了你的声音，我听第一句就知道是你——求你饶过我的孩子！", stability=0.0, gap_after_s=0.28),
        dlg("ma11_count_end", "audition", "monte_cristo", "基督山伯爵", "[softly] [solemn] 在上帝揭晓未来之前，人类全部的智慧，都包含在这五个字里——等待，和希望。", acoustic_space="studio_warm", gap_after_s=0.55),
    ]
    return EpisodeCueSheet(
        episode_id="AUDITION_MONTE_CRISTO",
        chapter_number=0,
        title="《基督山伯爵·伊夫堡复仇广播剧》核心声线与复仇名场面试听包",
        mode="audition_pack",
        head_pad_s=0.35,
        tail_pad_s=1.0,
        acts=[act("audition", "伊夫堡复仇核心试听", "paris_venetian_revenge", bgm_duration_s=60.0)],
        cues=cues,
    )


