        dlg("m02_41", "act4", "narrator", "史诗旁白", "一八二九年二月二十八日深夜，第三次中风夺走了法利亚神父的生命。次日清晨，狱卒把老人的遗体缝进一只粗糙的亚麻裹尸袋，准备天黑后按伊夫堡的老规矩丢进大海。", gap_after_s=0.26),
