        dlg("m03_10", "act2", "narrator", "史诗旁白", "加尔桥附近一间破败不堪的路边小客栈。身穿黑袍的意大利神父“布索尼”，正隔着摇曳的油灯打量着当年马赛的老裁缝——如今满脸愁苦、衣衫褴褛的卡德鲁斯。", gap_after_s=0.24),
