        dlg("m03_35", "act4", "narrator", "史诗旁白", "时光飞逝九年，来到一八三八年的罗马狂欢节。基督山伯爵早已周游东方、在君士坦丁堡赎回亡国公主海黛。在罗马旅馆阳台上，他故意向年轻的费尔南独子阿尔贝，吐露了一段令青年脊背发凉的话。", gap_after_s=0.26),
