        dlg("m03_36", "act4", "albert_max", "阿尔贝·德·莫尔塞夫", "[angry] [terrified] 放开我！你们这群罗马强盗知道我父亲是谁吗？他是法国莫尔塞夫伯爵！限你们天亮前松绑，否则法国军队会踏平你们的山洞！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.24),
