        dlg("m03_44", "act5", "narrator", "史诗旁白", "五月，两匹价值连城的纯黑骏马拉着镶金马车驶入巴黎香榭丽舍大道。伯爵拜访的第一座大门，便是当年左手写下黑信的会计、如今巴黎头号银行家唐格拉尔男爵的豪奢办公室。", gap_after_s=0.26),
